/* Example of logic: evaluate a postfix expression of single-digit operands
   separated by spaces. It was checked by a Python translation, not compiled. */
int evaluate(char expr[])
{
    int stack[20];
    int top = -1;
    int i, a, b;
    for (i = 0; expr[i] != '\0'; i++) {
        char c = expr[i];
        if (c >= '0' && c <= '9') {
            top++;
            stack[top] = c - '0';           /* push the operand */
        } else if (c != ' ') {
            b = stack[top--];               /* right operand comes off first */
            a = stack[top--];
            top++;
            if (c == '+')      stack[top] = a + b;
            else if (c == '-') stack[top] = a - b;
            else if (c == '*') stack[top] = a * b;
            else               stack[top] = a / b;
        }
    }
    return stack[top];                      /* the single value left */
}
```
For `"7 2 3 * - 4 +"` the function returns 5, the value of 7 - 2 x 3 + 4.
